import{_ as l,l as i,o as e,c as d,v as t,p as s,x as o,d as n,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"TMAH 与显影液","description":"","frontmatter":{"title":"TMAH 与显影液","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tmah-developer.md","filePath":"litho/tmah-developer.md","lastUpdated":1789023840000}'),m={name:"litho/tmah-developer.md"};function T(_,a,A,c,u,f){const r=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="tmah-与显影液" tabindex="-1">TMAH 与显影液 <a class="header-anchor" href="#tmah-与显影液" aria-label="Permalink to &quot;TMAH 与显影液&quot;">​</a></h1><div class="epigraph"><p>0.26 N TMAH 是正性 CAR 的工业默认碱；浓度、温度和表面活性剂改的是溶解阈值，不是空中像。</p><footer>—— 对照工业标准 tetramethylammonium hydroxide 显影液</footer></div><p><a href="/litho/develop-puddle">上一课</a>给出铺液方式。缺口是液体是什么：四甲基氢氧化铵（TMAH）水溶液，常标 2.38 wt%（约 0.26 N）。主干胶课假定「碱显影」；本课钉这一默认契约，以及为什么不能当纯水漂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正胶曝光区聚合物变亲水、可溶。碱浓度决定阈值：过稀，该溶的不溶；过浓，未曝光区也咬。温度几度就改速率，轨道显影模块的液温是 CDU 源。把显影液当成「水」，会把化学对比度派给 PEB。</p><p><span class="marginnote">TMAH 有毒性与废水约束，厂内是危险化学品管理对象。本课只写工艺角色，不写操作规程替代 MSDS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>浓度、温度、表面活性剂（下一课冲洗也会用）写进配方。新鲜液对循环液：循环降低成本，但带溶解产物，阈值漂。过滤与补给是缺陷课的前置。负胶或金属氧化物胶可能不用 TMAH——本课不吞并。</p>',8)),(e(),s(p,null,{default:o(()=>[h(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TMAH%5B%220.26%20N%20TMAH%22%5D%20--%3E%20THR%5B%22%E6%BA%B6%E8%A7%A3%E9%98%88%E5%80%BC%22%5D%0A%20%20TEMP%5B%22%E6%B6%B2%E6%B8%A9%22%5D%20--%3E%20THR%0A%20%20THR%20--%3E%20CD%5B%22%E7%BA%BF%E5%AE%BD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>酚羟基（或 CAR 脱保护后的羧酸）在碱中电离，聚合物链溶剂化后离开膜。离子强度改双电层与溶胀，从而改倒塌风险——后课倒塌抑制会回到液面张力，不全是 TMAH 浓度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写有机溶剂显影或干法显影化学。下一课冲洗：把碱和产物带走，毛细力开始主导。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工业正胶默认 0.26 N TMAH；浓度与温度是 CD 旋钮。</li><li>循环污染会漂阈值。</li><li>出处：TMAH 显影工业通识；Mack 溶解语境。</li></ul>',6))])}const E=l(m,[["render",T]]);export{B as __pageData,E as default};
